17	package org.springframework.samples.petclinic.rest.advice;
18	
19	import java.net.URI;
20	import java.time.Instant;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import jakarta.servlet.http.HttpServletRequest;
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.dao.DataIntegrityViolationException;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ProblemDetail;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.controller.BindingErrorsResponse;
32	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
33	import org.springframework.security.access.AccessDeniedException;
34	import org.springframework.validation.BindingResult;
35	import org.springframework.validation.FieldError;
36	import org.springframework.web.bind.MethodArgumentNotValidException;
37	import org.springframework.web.bind.annotation.ControllerAdvice;
38	import org.springframework.web.bind.annotation.ExceptionHandler;
39	import org.springframework.web.bind.annotation.ResponseBody;
40	
41	/**
42	 * Global Exception handler for REST controllers.
43	 * <p>
44	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
45	 *
46	 * @author Vitaliy Fedoriv
47	 * @author Alexander Dudkin
48	 */
49	@ControllerAdvice
50	public class ExceptionControllerAdvice {
51	
52	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
53	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
54	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
55	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
56	
57	    /**
58	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
59	     * class.
60	     *
61	     * @param e     Object referring to the thrown exception.
62	     * @param status HTTP response status.
63	     * @param url URL request.
64	     */
65	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
66	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
67	        problemDetail.setType(URI.create(url.toString()));
68	        problemDetail.setTitle(e.getClass().getSimpleName());
69	        problemDetail.setDetail(detail);
70	        problemDetail.setProperty("timestamp", Instant.now());
71	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
72	        return problemDetail;
73	    }
74	
75	    /**
76	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
77	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
78	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
79	     * would catch it and report an authorization failure as a 500.
80	     *
81	     * @param e The {@link AccessDeniedException} to propagate
82	     * @throws AccessDeniedException always
83	     */
84	    @ExceptionHandler(AccessDeniedException.class)
85	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
86	        throw e;
87	    }
88	
89	    /**
90	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
91	     *
92	     * @param e The {@link Exception} to be handled
93	     * @param request {@link HttpServletRequest} object referring to the current request.
94	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
95	     */
96	    @ExceptionHandler(Exception.class)
97	    @ResponseBody
98	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
99	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
100	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
101	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
102	        return ResponseEntity.status(status).body(detail);
103	    }
104	
105	    /**
106	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
107	     * method returns a 404 Not Found status if an entity does not exist.
108	     *
109	     * @param e The {@link DataIntegrityViolationException} to be handled
110	     * @param request {@link HttpServletRequest} object referring to the current request.
111	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
112	     */
113	    @ExceptionHandler(DataIntegrityViolationException.class)
114	    @ResponseBody
115	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
116	        logger.warn("Data integrity violation at {} {}: {}",
117	            request.getMethod(),
118	            request.getRequestURI(),
119	            e.getMessage());
120	        logger.debug("Data integrity violation stacktrace", e);
121	        HttpStatus status = HttpStatus.NOT_FOUND;
122	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
123	        return ResponseEntity.status(status).body(detail);
124	    }
125	
126	    /**
127	     * Handles exception thrown by Bean Validation on controller methods parameters
128	     *
129	     * @param e The {@link MethodArgumentNotValidException} to be handled
130	     * @param request {@link HttpServletRequest} object referring to the current request.
131	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
132	     */
133	    @ExceptionHandler(MethodArgumentNotValidException.class)
134	    @ResponseBody
135	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
136	        HttpStatus status = HttpStatus.BAD_REQUEST;
137	        BindingErrorsResponse errors = new BindingErrorsResponse();
138	        BindingResult bindingResult = e.getBindingResult();
139	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
140	        List<String> invalidFields = bindingResult.getFieldErrors().stream()
141	            .map(FieldError::getField)
142	            .distinct()
143	            .toList();
144	        detail.setProperty("errors", invalidFields);
145	        if (bindingResult.hasErrors()) {
146	            errors.addAllErrors(bindingResult);
147	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
148	                .map(fieldError -> {
149	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
150	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
151	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
152	                        fieldError.getField(),
153	                        defaultMessage,
154	                        rejectedValue);
155	                    return new ValidationMessageDto(message)
156	                        .putAdditionalProperty("field", fieldError.getField())
157	                        .putAdditionalProperty("rejectedValue", rejectedValue)
158	                        .putAdditionalProperty("defaultMessage", defaultMessage);
159	                })
160	                .toList();
161	            logger.debug("Validation error at {} {}: {}",
162	                request.getMethod(),
163	                request.getRequestURI(),
164	                bindingResult.getFieldErrors());
165	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
166	            return ResponseEntity.status(status).body(detail);
167	        }
168	        return ResponseEntity.status(status).body(detail);
169	    }
170	
171	    /**
172	     * Handles {@link InvalidOwnerFieldsException} raised when an owner is created or edited while
173	     * missing or blank in one or more required fields. Returns a 400 Bad Request whose body carries
174	     * an {@code errors} array listing the name of each rejected field.
175	     *
176	     * @param e The {@link InvalidOwnerFieldsException} to be handled
177	     * @param request {@link HttpServletRequest} object referring to the current request.
178	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
179	     */
180	    @ExceptionHandler(InvalidOwnerFieldsException.class)
181	    @ResponseBody
182	    public ResponseEntity<ProblemDetail> handleInvalidOwnerFieldsException(InvalidOwnerFieldsException e, HttpServletRequest request) {
183	        HttpStatus status = HttpStatus.BAD_REQUEST;
184	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
185	        detail.setProperty("errors", e.getFields());
186	        logger.debug("Missing or blank owner fields at {} {}: {}",
187	            request.getMethod(),
188	            request.getRequestURI(),
189	            e.getFields());
190	        return ResponseEntity.status(status).body(detail);
191	    }
192	
193	    /**
194	     * Handles {@link DuplicateOwnerTelephoneException} raised when an owner is created with a
195	     * telephone whose normalized form is already used by another owner. Returns a 409 Conflict.
196	     *
197	     * @param e The {@link DuplicateOwnerTelephoneException} to be handled
198	     * @param request {@link HttpServletRequest} object referring to the current request.
199	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
200	     */
201	    @ExceptionHandler(DuplicateOwnerTelephoneException.class)
202	    @ResponseBody
203	    public ResponseEntity<ProblemDetail> handleDuplicateOwnerTelephoneException(DuplicateOwnerTelephoneException e, HttpServletRequest request) {
204	        HttpStatus status = HttpStatus.CONFLICT;
205	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
206	        detail.setProperty("errors", List.of("telephone"));
207	        logger.debug("Duplicate owner telephone at {} {}: {}",
208	            request.getMethod(),
209	            request.getRequestURI(),
210	            e.getTelephone());
211	        return ResponseEntity.status(status).body(detail);
212	    }
213	
214	    /**
215	     * Handles {@link DuplicateOwnerEmailException} raised when an owner is created with an email
216	     * whose lower-cased form is already used by another owner. Returns a 409 Conflict.
217	     *
218	     * @param e The {@link DuplicateOwnerEmailException} to be handled
219	     * @param request {@link HttpServletRequest} object referring to the current request.
220	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
221	     */
222	    @ExceptionHandler(DuplicateOwnerEmailException.class)
223	    @ResponseBody
224	    public ResponseEntity<ProblemDetail> handleDuplicateOwnerEmailException(DuplicateOwnerEmailException e, HttpServletRequest request) {
225	        HttpStatus status = HttpStatus.CONFLICT;
226	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
227	        detail.setProperty("errors", List.of("email"));
228	        logger.debug("Duplicate owner email at {} {}: {}",
229	            request.getMethod(),
230	            request.getRequestURI(),
231	            e.getEmail());
232	        return ResponseEntity.status(status).body(detail);
233	    }
234	
235	    /**
236	     * Handles {@link DuplicateOwnerHouseholdException} raised when an owner is created whose last
237	     * name and address (compared case-insensitively with collapsed whitespace) already belong to
238	     * another owner and the request did not opt in via {@code sharesHousehold}. Returns a 409
239	     * Conflict.
240	     *
241	     * @param e The {@link DuplicateOwnerHouseholdException} to be handled
242	     * @param request {@link HttpServletRequest} object referring to the current request.
243	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
244	     */
245	    @ExceptionHandler(DuplicateOwnerHouseholdException.class)
246	    @ResponseBody
247	    public ResponseEntity<ProblemDetail> handleDuplicateOwnerHouseholdException(DuplicateOwnerHouseholdException e, HttpServletRequest request) {
248	        HttpStatus status = HttpStatus.CONFLICT;
249	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
250	        detail.setProperty("errors", List.of("lastName", "address"));
251	        logger.debug("Duplicate owner household at {} {}: {}, {}",
252	            request.getMethod(),
253	            request.getRequestURI(),
254	            e.getLastName(),
255	            e.getAddress());
256	        return ResponseEntity.status(status).body(detail);
257	    }
258	
259	    /**
260	     * Handles {@link DuplicateOwnerIdentityException} raised when a request to create an owner
261	     * produces an {@code identityKey} ({@code normalizedTelephone + '|' + (email or empty) + '|' +
262	     * householdId}) that exactly matches an existing owner's. This single key consolidates the
263	     * former separate telephone, email and household duplicate checks. Returns a 409 Conflict.
264	     *
265	     * @param e The {@link DuplicateOwnerIdentityException} to be handled
266	     * @param request {@link HttpServletRequest} object referring to the current request.
267	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
268	     */
269	    @ExceptionHandler(DuplicateOwnerIdentityException.class)
270	    @ResponseBody
271	    public ResponseEntity<ProblemDetail> handleDuplicateOwnerIdentityException(DuplicateOwnerIdentityException e, HttpServletRequest request) {
272	        HttpStatus status = HttpStatus.CONFLICT;
273	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
274	        detail.setProperty("errors", List.of("identityKey"));
275	        logger.debug("Duplicate owner identity at {} {}: {}",
276	            request.getMethod(),
277	            request.getRequestURI(),
278	            e.getIdentityKey());
279	        return ResponseEntity.status(status).body(detail);
280	    }
281	
282	    /**
283	     * Handles {@link CityAtCapacityException} raised when an owner is created in a city that already
284	     * contains the maximum number of owners (50). Returns a 409 Conflict.
285	     *
286	     * @param e The {@link CityAtCapacityException} to be handled
287	     * @param request {@link HttpServletRequest} object referring to the current request.
288	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
289	     */
290	    @ExceptionHandler(CityAtCapacityException.class)
291	    @ResponseBody
292	    public ResponseEntity<ProblemDetail> handleCityAtCapacityException(CityAtCapacityException e, HttpServletRequest request) {
293	        HttpStatus status = HttpStatus.CONFLICT;
294	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
295	        detail.setProperty("errors", List.of("city"));
296	        logger.debug("City at capacity at {} {}: {}",
297	            request.getMethod(),
298	            request.getRequestURI(),
299	            e.getCity());
300	        return ResponseEntity.status(status).body(detail);
301	    }
302	
303	    /**
304	     * Handles {@link DailyOwnerLimitExceededException} raised when an owner is created after the
305	     * maximum number of owners for the day (100) has already been reached. Returns a 429 Too Many
306	     * Requests.
307	     *
308	     * @param e The {@link DailyOwnerLimitExceededException} to be handled
309	     * @param request {@link HttpServletRequest} object referring to the current request.
310	     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status.
311	     */
312	    @ExceptionHandler(DailyOwnerLimitExceededException.class)
313	    @ResponseBody
314	    public ResponseEntity<ProblemDetail> handleDailyOwnerLimitExceededException(DailyOwnerLimitExceededException e, HttpServletRequest request) {
315	        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
316	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
317	        detail.setProperty("errors", List.of("registrationDate"));
318	        logger.debug("Daily owner limit exceeded at {} {}: {}",
319	            request.getMethod(),
320	            request.getRequestURI(),
321	            e.getDate());
322	        return ResponseEntity.status(status).body(detail);
323	    }
324	
325	    /**
326	     * Handles {@link FutureRegistrationDateException} raised when an owner is created with a supplied
327	     * registration date that is later than the server's current date. Returns a 400 Bad Request whose
328	     * body carries an {@code errors} array naming the rejected field.
329	     *
330	     * @param e The {@link FutureRegistrationDateException} to be handled
331	     * @param request {@link HttpServletRequest} object referring to the current request.
332	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
333	     */
334	    @ExceptionHandler(FutureRegistrationDateException.class)
335	    @ResponseBody
336	    public ResponseEntity<ProblemDetail> handleFutureRegistrationDateException(FutureRegistrationDateException e, HttpServletRequest request) {
337	        HttpStatus status = HttpStatus.BAD_REQUEST;
338	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
339	        detail.setProperty("errors", List.of("registrationDate"));
340	        logger.debug("Future registration date at {} {}: {}",
341	            request.getMethod(),
342	            request.getRequestURI(),
343	            e.getDate());
344	        return ResponseEntity.status(status).body(detail);
345	    }
346	
347	}
